package com.gymmind.membership.api; import com.gymmind.membership.application.*; import com.gymmind.shared.api.ApiResponse; import com.gymmind.shared.security.CurrentActorProvider; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.time.Instant; @RestController @RequestMapping("/api/v1/memberships") @SecurityRequirement(name="bearerAuth") public class MemberMembershipController{private final MemberMembershipService service;private final CurrentActorProvider actors;public MemberMembershipController(MemberMembershipService s,CurrentActorProvider a){service=s;actors=a;}@PostMapping @ResponseStatus(HttpStatus.CREATED)public ApiResponse<MemberMembershipView>grant(@Valid@RequestBody GrantRequest r){return ApiResponse.success(service.grant(actors.requireCurrent(),new GrantMembershipCommand(null,r.memberId(),r.packageId(),r.startsAt(),r.expiresAt())));}public record GrantRequest(Long memberId,Long packageId,Instant startsAt,Instant expiresAt){}}
